args.ReplacementContent:
.floating-nav-capsule {
    position: fixed;
    top: 8px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1100;
    padding: 3px 5px;
    background: rgba(14, 14, 18, 0.94);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow: 0 4px 22px rgba(0, 0, 0, 0.7);
    max-width: calc(100vw - 12px);
    width: max-content;
    box-sizing: border-box;
    gap: 2px;
    transition: all var(--transition-fast);
}

body.view-tv-active .floating-nav-capsule {
    max-width: calc(100vw - 12px);
}

.nav-capsule-item {
    padding: 5px 8px;
    font-size: 0.70rem;
    gap: 4px;
    flex-shrink: 0;
    border-radius: 9999px;
    transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.nav-capsule-badge {
    display: none !important; /* Hide 'Em Breve' badge text to keep capsule compact on mobile */
}

/* On mobile/tablet screens (<=768px), inactive tabs display sleek icons while active tab expands with label */
.nav-capsule-item:not(.active) span:not(.nav-capsule-badge) {
    display: none !important;
}

.nav-capsule-item {
    padding: 5px 8px;
}

.nav-capsule-item.active {
    padding: 5px 11px;
}

.nav-capsule-icon {
    width: 15px;
    height: 15px;
}

