    transform: translateX(-50%);
    z-index: 1100;
    padding: 3px 5px;
    background: rgba(14, 14, 18, 0.94);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    box-shadow: 0 4px 22px rgba(0, 0, 0, 0.7);
    max-width: calc(100vw - 16px);
    width: max-content;
    gap: 3px;
    transition: all var(--transition-fast);
}

body.view-tv-active .floating-nav-capsule {
    max-width: calc(100vw - 110px);
}

.nav-capsule-item {
    padding: 5px 8px;
    font-size: 0.70rem;
    gap: 4px;
    flex-shrink: 0;
    transition: all 0.22s cubic-bezier(0.16, 1, 0.3, 1);
}

.nav-capsule-badge {
    display: none !important; /* Hide 'Em Breve' badge text to keep capsule compact on mobile */
}

/* On mobile screens (<600px), inactive tabs display sleek icons while active tab expands with label */
@media (max-width: 600px) {
    .floating-nav-capsule {
        max-width: calc(100vw - 12px);
