                            return item.html;
                        }
                    });
                };

                hls.on(window.Hls.Events.MANIFEST_PARSED, (event, data) => {
                    markStreamSuccess();
                    if (data.levels && data.levels.length > 1) {
                        const qualities = data.levels.map((lvl, idx) => ({
                            default: idx === hls.currentLevel,
                            html: `${lvl.height ? lvl.height + 'p' : 'Auto'} (${Math.round(lvl.bitrate / 1000)}k)`,
                            levelIndex: idx
                        }));
                        qualities.unshift({ default: true, html: 'Automático', levelIndex: -1 });

                        artInstance.setting.add({
                            id: 'quality-selector',
                            name: 'Qualidade',
                            width: 150,
                            tooltip: 'Auto',
                            selector: qualities,
                            onSelect: function (item) {
                                hls.currentLevel = item.levelIndex;
                                return item.html;
                            }
                        });
                    }
                    registerAudioTracks();
                });

                hls.on(window.Hls.Events.AUDIO_TRACKS_UPDATED, () => {
                    registerAudioTracks();
                });

                hls.on(window.Hls.Events.ERROR, (event, data) => {
                    if (data.fatal) {
                        switch (data.type) {
                            case window.Hls.ErrorTypes.NETWORK_ERROR:
                                hls.startLoad();
                                break;
                            case window.Hls.ErrorTypes.MEDIA_ERROR:
                                hls.recoverMediaError();
                                break;
                            default:
                                tryFallback();
                                break;
                        }
                    }
                });
            } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
                video.src = url;
                video.addEventListener('loadedmetadata', () => {
                    markStreamSuccess();
                }, { once: true });
            }
        }
    }
});

