const SERIES_SERVER_OPTIONS = [
    { id: 'native_direct', name: 'Player Nativo - Sem Anúncios (BETA)', isNative: true },
    { id: 'native_anime',  name: 'Player Nativo Animes - Sem Anúncios (BETA)', isNative: true, animeOnly: true },
